import { useField } from 'formik';
import { cn } from '@/lib/utils';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

interface FormikTextFieldProps {
  name: string;
  label?: string;
  placeholder?: string;
  type?: string;
  disabled?: boolean;
  className?: string;
  containerClassName?: string;
  maxLength?: number;
  startIcon?: React.ReactNode;
  endIcon?: React.ReactNode;
  textarea?: boolean;
  rows?: number;
  showRequiredIcon?: boolean;
  onChange?: (value: string) => void;
}

/**
 * Formik bağlantılı Input (MSI UI Kit).
 * Hata mesajı ve touched durumunu otomatik yönetir.
 *
 * @example
 * <FormikTextField name="email" label="E-posta" type="email" />
 */
export function FormikTextField({
  name,
  label,
  placeholder,
  type = 'text',
  disabled,
  className,
  containerClassName,
  maxLength,
  startIcon,
  endIcon,
  textarea,
  rows,
  showRequiredIcon,
  onChange,
}: FormikTextFieldProps) {
  const [field, meta, helpers] = useField(name);

  return (
    <div className={cn('flex flex-col gap-1.5', containerClassName)}>
      {label && (
        <Label htmlFor={name}>
          {label}
          {showRequiredIcon && <span className="text-red-500"> *</span>}
        </Label>
      )}
      <Input
        id={name}
        value={field.value ?? ''}
        onChange={(e) => {
          helpers.setValue(e.target.value);
          onChange?.(e.target.value);
        }}
        onBlur={field.onBlur}
        type={type}
        placeholder={placeholder}
        disabled={disabled}
        maxLength={maxLength}
        startIcon={startIcon}
        endIcon={endIcon}
        textarea={textarea}
        rows={rows}
        error={!!(meta.touched && meta.error)}
        className={cn(className)}
      />
      {meta.touched && meta.error && (
        <span className="text-xs font-medium text-red-500">{meta.error}</span>
      )}
    </div>
  );
}

import { useField } from 'formik';
import { cn } from '@/lib/utils';
import Select, { type ISelectOption } from '@/components/ui/select';

interface FormikSelectOption {
  value: string | number;
  label: string;
}

interface FormikSelectProps {
  name: string;
  label?: string;
  options: FormikSelectOption[];
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  isMulti?: boolean;
  isSearchable?: boolean;
  showRequiredIcon?: boolean;
  onChange?: (value: unknown) => void;
}

/**
 * Formik bağlantılı Select (MSI UI Kit Select).
 *
 * @example
 * <FormikSelect name="role" label="Rol" options={[{ value: 'admin', label: 'Admin' }]} />
 */
export function FormikSelect({
  name,
  label,
  options,
  placeholder = 'Seçiniz...',
  disabled,
  className,
  isMulti = false,
  isSearchable = false,
  showRequiredIcon,
  onChange,
}: FormikSelectProps) {
  const [field, meta, helpers] = useField(name);

  // MSI Select ISelectOption uses `content` field instead of `label`
  const msiOptions: ISelectOption[] = options.map((o) => ({
    value: o.value,
    content: o.label,
  }));

  return (
    <div className={cn(className)}>
      <Select
        id={name}
        label={label}
        showRequiredIcon={showRequiredIcon}
        value={field.value ?? ''}
        onChange={(value) => {
          helpers.setValue(value);
          helpers.setTouched(true);
          onChange?.(value);
        }}
        placeHolder={placeholder}
        options={msiOptions}
        isMulti={isMulti}
        isSearchable={isSearchable}
        disabled={disabled}
        error={!!(meta.touched && meta.error)}
      />
      {meta.touched && meta.error && (
        <span className="text-xs font-medium text-red-500">{meta.error}</span>
      )}
    </div>
  );
}

import { useField } from 'formik';
import { cn } from '@/lib/utils';
import { Checkbox } from '@/components/ui/checkbox';

interface FormikCheckboxProps {
  name: string;
  label?: string;
  disabled?: boolean;
  className?: string;
  containerClassName?: string;
  labelClassName?: string;
  labelSide?: 'left' | 'right';
  onChange?: (checked: boolean) => void;
}

/**
 * Formik bağlantılı Checkbox (MSI UI Kit).
 *
 * @example
 * <FormikCheckbox name="agree" label="Kabul ediyorum" />
 */
export function FormikCheckbox({
  name,
  label,
  disabled,
  className,
  containerClassName,
  labelClassName,
  labelSide = 'right',
  onChange,
}: FormikCheckboxProps) {
  const [field, meta, helpers] = useField({ name, type: 'checkbox' });

  return (
    <div className={cn('flex flex-col gap-1', containerClassName)}>
      <div className="flex items-center gap-2">
        <Checkbox
          id={name}
          checked={field.value ?? false}
          onCheckedChange={(checked) => {
            helpers.setValue(checked);
            helpers.setTouched(true);
            onChange?.(checked as boolean);
          }}
          disabled={disabled}
          className={cn(className)}
          label={label}
          labelSide={labelSide}
          labelClassName={cn(labelClassName)}
        />
      </div>
      {meta.touched && meta.error && (
        <span className="text-xs font-medium text-red-500">{meta.error}</span>
      )}
    </div>
  );
}

import { useField } from 'formik';
import { cn } from '@/lib/utils';
import DatePicker from '@/components/ui/date-picker';
import { Label } from '@/components/ui/label';
import type { DayPickerProps } from 'react-day-picker';

interface FormikDatePickerProps {
  name: string;
  label?: string;
  disabled?: boolean;
  minDate?: Date;
  maxDate?: Date;
  className?: string;
  mode?: DayPickerProps['mode'];
  showRequiredIcon?: boolean;
  showClearButton?: boolean;
  showCompleteButton?: boolean;
  onBlur?: () => void;
}

/**
 * Formik bağlantılı DatePicker (MSI UI Kit).
 *
 * @example
 * <FormikDatePicker name="birthDate" label="Doğum Tarihi" />
 */
export function FormikDatePicker({
  name,
  label,
  disabled,
  minDate,
  maxDate,
  className,
  mode = 'single',
  showRequiredIcon,
  showClearButton = false,
  showCompleteButton,
  onBlur,
}: FormikDatePickerProps) {
  const [field, meta, helpers] = useField(name);

  return (
    <div className={cn('flex flex-col gap-1.5', className)}>
      {label && (
        <Label htmlFor={name}>
          {label}
          {showRequiredIcon && <span className="text-red-500"> *</span>}
        </Label>
      )}
      <DatePicker
        mode={mode}
        value={field.value ?? ''}
        disabled={disabled}
        minDate={minDate}
        maxDate={maxDate}
        showClearButton={showClearButton}
        showCompleteButton={showCompleteButton}
        error={!!(meta.touched && meta.error)}
        onChange={(val) => {
          if (mode === 'range') {
            helpers.setValue(val);
          } else {
            const d = val instanceof Date && !Number.isNaN(val.getTime())
              ? new Date(Date.UTC(val.getFullYear(), val.getMonth(), val.getDate()))
              : null;
            helpers.setValue(d);
          }
          helpers.setTouched(true);
        }}
        onBlur={onBlur}
      />
      {meta.touched && meta.error && (
        <span className="text-xs font-medium text-red-500">{meta.error}</span>
      )}
    </div>
  );
}

import { useField } from 'formik';
import { cn } from '@/lib/utils';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-buttons';

interface Option {
  value: string;
  label?: string;
}

interface FormikRadioButtonsProps {
  name: string;
  label?: string;
  options: Option[];
  disabled?: boolean;
  className?: string;
  onChange?: (value: string) => void;
}

/**
 * Formik bağlantılı RadioGroup (MSI UI Kit RadioButtons).
 *
 * @example
 * <FormikRadioButtons name="type" options={[{ value: 'a', label: 'A' }]} />
 */
export function FormikRadioButtons({
  name,
  label,
  options,
  disabled,
  className,
  onChange,
}: FormikRadioButtonsProps) {
  const [field, meta, helpers] = useField(name);

  return (
    <div className={cn('flex flex-col gap-1.5', className)}>
      {label && (
        <span className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
          {label}
        </span>
      )}
      <RadioGroup
        defaultValue={field.value ?? ''}
        onChange={(val) => {
          helpers.setValue(val);
          helpers.setTouched(true);
          if (val !== undefined) onChange?.(String(val));
        }}
      >
        {options.map((opt) => (
          <RadioGroupItem
            key={opt.value}
            id={`${name}-${opt.value}`}
            value={opt.value}
            label={opt.label}
            name={name}
            disabled={disabled}
          />
        ))}
      </RadioGroup>
      {meta.touched && meta.error && (
        <span className="text-xs font-medium text-red-500">{meta.error}</span>
      )}
    </div>
  );
}

import { useField } from 'formik';
import { cn } from '@/lib/utils';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';

interface FormikSwitchProps {
    name: string;
    label?: string;
    disabled?: boolean;
    className?: string;
    containerClassName?: string;
    labelClassName?: string;
    labelSide?: 'left' | 'right';
    onChange?: (checked: boolean) => void;
}

/**
 * Formik bağlantılı Switch (MSI UI Kit).
 *
 * @example
 * <FormikSwitch name="isActive" label="Aktif" />
 */
export function FormikSwitch({
    name,
    label,
    disabled,
    className,
    containerClassName,
    labelClassName,
    labelSide = 'right',
    onChange,
}: FormikSwitchProps) {
    const [field, meta, helpers] = useField(name);

    return (
        <div className={cn('flex flex-col gap-1.5', containerClassName)}>
            <div className="flex items-center gap-2">
                {label && labelSide === 'left' && (
                    <Label htmlFor={name} className={cn(labelClassName)}>
                        {label}
                    </Label>
                )}
                <Switch
                    id={name}
                    checked={field.value ?? false}
                    onCheckedChange={(checked) => {
                        helpers.setValue(checked);
                        helpers.setTouched(true);
                        onChange?.(checked);
                    }}
                    disabled={disabled}
                    className={cn(className)}
                />
                {label && labelSide === 'right' && (
                    <Label htmlFor={name} className={cn(labelClassName)}>
                        {label}
                    </Label>
                )}
            </div>
            {meta.touched && meta.error && (
                <span className="text-xs font-medium text-red-500">{meta.error}</span>
            )}
        </div>
    );
}

export { FormikTextField } from './formik-text-field';
export { FormikSelect } from './formik-select';
export { FormikCheckbox } from './formik-checkbox';
export { FormikDatePicker } from './formik-date-picker';
export { FormikRadioButtons } from './formik-radio-buttons';
export { FormikSwitch } from './formik-switch';
